window.COLLATION={"edition": "2026-10-17", "records": {"D1-01": {"source_id": "D1-01", "title": "Kunsten er død", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese B: Kunsten er død", "url": "manuscript.html#p323", "paragraph": 323}, {"label": "Antitese i manuskriptet", "text": "Antitese B: Kunsten genfødes konstant.", "url": "manuscript.html#p333", "paragraph": 333}], "related": [{"id": "D4-02", "title": "Metatese 2"}], "historical": {"url": "archive/2023/disput-1/transcription_and_synthesis_20230918164901.txt", "filename": "transcription_and_synthesis_20230918164901.txt", "synthesis": "Max Y. Locusus og Maxia Anna Niknolds teorier om den transgressive kunst som et moderne udtryk, der repræsenteres ved Edmund Holmgård Nielsens projekt Lumpen Intelligensia og Computer Ligetures konjunkturprojekt, giver et nyt perspektiv på kunstens muligheder for liberation.", "label": "Syntese fra 2023"}}, "D1-02": {"source_id": "D1-02", "title": "Revolutionen er repræsenterbar", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese A: Revolutionen er repræsenterbar.", "url": "manuscript.html#p322", "paragraph": 322}, {"label": "Antitese i manuskriptet", "text": "Antitese A: Revolutionen er en indre bevidsthedsstrøm.", "url": "manuscript.html#p332", "paragraph": 332}], "related": [{"id": "D1-06", "title": "Publiciteten er transmonarkisk"}, {"id": "D2-07", "title": "Computer Lars operationaliserer tredjeheden"}], "historical": {"url": "archive/2023/disput-1/transcription_and_synthesis_20230918171436.txt", "filename": "transcription_and_synthesis_20230918171436.txt", "synthesis": "ComputeLabs-projektet udfordrer regler og normer i det statlige og kapitalistiske system ved at kombinere post-representative former, modstandsformer og velvilje-repræsentationer sammen for at skabe et kritisk modbillede.", "label": "Syntese fra 2023"}}, "D1-03": {"source_id": "D1-03", "title": "Fascisme og demokrati er ikke modsætninger", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese D: Fascisme og demokrati er ikke modsætninger", "url": "manuscript.html#p325", "paragraph": 325}, {"label": "Antitese i manuskriptet", "text": "Antitese D: Fascisme og demokrati er modpoler.", "url": "manuscript.html#p335", "paragraph": 335}], "related": [], "historical": {"url": "archive/2023/disput-1/transcription_and_synthesis_20230918175740.txt", "filename": "transcription_and_synthesis_20230918175740.txt", "synthesis": "Fascisme og demokrati er ikke-modsætnigner, som kan bedre forstås gennem en konjunkturel analyse af nye former for sammenhænge mellem demokratisam, fascisme, karkistokrati og ældre ungdom.", "label": "Syntese fra 2023"}}, "D1-04": {"source_id": "D1-04", "title": "Teknikken er revolutionens stilistik", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese C: Teknikken er revolutionens stilistik.", "url": "manuscript.html#p324", "paragraph": 324}, {"label": "Antitese i manuskriptet", "text": "Antitese C: Teknikken dæmper revolutionens flamme.", "url": "manuscript.html#p334", "paragraph": 334}], "related": [{"id": "D3-03", "title": "Den kybernetiske operationalisering tilvejebringer aposterioriske virkelighedsbetingelser pr. analogi"}, {"id": "D4-08", "title": "Metatese 8"}, {"id": "D4-09", "title": "Metatese 9"}], "historical": {"url": "archive/2023/disput-1/transcription_and_synthesis_20230918182620.txt", "filename": "transcription_and_synthesis_20230918182620.txt", "synthesis": "Computer Lars fremfører en revolutionær teknik, der anvendes til at producere tekst, transskribere kapitalvalutate og skabe en tragisk forståelse af teknologi som et problematisk tema, der genererer nye biologiske subjekter uden horisont eller udsigt til fremtiden.", "label": "Syntese fra 2023"}}, "D1-05": {"source_id": "D1-05", "title": "Offentlighed og opstand er modsætninger", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese F: Offentlighed og opstand er modsætninger", "url": "manuscript.html#p327", "paragraph": 327}, {"label": "Antitese i manuskriptet", "text": "Antitese F: Offentlighed og opstand nærer hinanden.", "url": "manuscript.html#p337", "paragraph": 337}], "related": [], "historical": {"url": "archive/2023/disput-1/transcription_and_synthesis_20230918190342.txt", "filename": "transcription_and_synthesis_20230918190342.txt", "synthesis": "Offentlighed og opstand fremmer et alternativ til den habermasianske ideologi, som åbner grænser for magtsudøvelse, og opmuntrer forskellige offentligheder og mediebrugere.", "label": "Syntese fra 2023"}}, "D1-06": {"source_id": "D1-06", "title": "Publiciteten er transmonarkisk", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese E: Publiciteten er trans-monarkisk.", "url": "manuscript.html#p326", "paragraph": 326}, {"label": "Antitese i manuskriptet", "text": "Antitese E: Publiciteten er fastankret i det frie marked.", "url": "manuscript.html#p336", "paragraph": 336}], "related": [{"id": "D1-02", "title": "Revolutionen er repræsenterbar"}, {"id": "D2-07", "title": "Computer Lars operationaliserer tredjeheden"}], "historical": {"url": "archive/2023/disput-1/transcription_and_synthesis_20230918192412.txt", "filename": "transcription_and_synthesis_20230918192412.txt", "synthesis": "Foucault's undersøgelse af pastorale og monarkiske magtformer i forhold til mediedækning af 9/11, finanskrisen og Trump-politikken belyser, hvordan publicitet er blevet transmonarkisk og implicerer en overskridelse af det nationale fællesskab.", "label": "Syntese fra 2023"}}, "D1-07": {"source_id": "D1-07", "title": "Dialektikken er gået i stykker", "written": [{"label": "Hypotese i manuskriptet", "text": "-   Hypotese H: Dialektikken er gået i stykker", "url": "manuscript.html#p329", "paragraph": 329}, {"label": "Antitese i manuskriptet", "text": "Antitese H: Dialektikken er i konstant evolution.", "url": "manuscript.html#p339", "paragraph": 339}], "related": [{"id": "D2-08", "title": "En emancipatorisk kombinatorik negerer ethvert aggregat"}, {"id": "D4-19", "title": "Metatese 19"}], "historical": {"url": "archive/2023/disput-1/transcription_and_synthesis_20230918195942.txt", "filename": "transcription_and_synthesis_20230918195942.txt", "synthesis": "Udfordringerne ved halvmærkets offentlighedsbeklædelighed har krævet innovative løsninger for at undgå dialektikkens brud og opretholde historiens lovmæssigheder.", "label": "Syntese fra 2023"}}, "D1-08": {"source_id": "D1-08", "title": "Revolutionen er entropisk", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese G: Revolutionen er entropisk.", "url": "manuscript.html#p328", "paragraph": 328}, {"label": "Antitese i manuskriptet", "text": "Antitese G: Revolutionen er en skabende orden.", "url": "manuscript.html#p338", "paragraph": 338}], "related": [], "historical": {"url": "archive/2023/disput-1/transcription_and_synthesis_20230918202001.txt", "filename": "transcription_and_synthesis_20230918202001.txt", "synthesis": "Revolutionen er et fællesskab, der arbejder for at omfavne det tropiske princip for entropi og producere et lykkeligere kosmisk billede gennem transhumanisme og virale tilstedeværelser.", "label": "Syntese fra 2023"}}, "D2-01": {"source_id": "D2-01", "title": "Computer Lars er flad", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese B: Computer Lars er flad.", "url": "manuscript.html#p348", "paragraph": 348}, {"label": "Antitese i manuskriptet", "text": "Antitese B: Computer Lars er tredimensionel.", "url": "manuscript.html#p358", "paragraph": 358}], "related": [], "historical": {"url": "archive/2023/disput-2/transcription_and_synthesis_20230920184252.txt", "filename": "transcription_and_synthesis_20230920184252.txt", "synthesis": "Computer Lars' paradoksale rumtid, som kombinerer dyb teori, forberedelser og metafysik for at omdanne binære kategorier til vektoriserede, provokerer refleksive æstetiske refleksioner mod den digitale kultur.", "label": "Syntese fra 2023"}}, "D2-02": {"source_id": "D2-02", "title": "Netværket findes ikke, ergo eksisterer Computer Lars", "written": [{"label": "Hypotese i manuskriptet", "text": "Hypotese A: Netværket findes ikke, ergo eksisterer Computer Lars.", "url": "manuscript.html#p347", "paragraph": 347}, {"label": "Antitese i manuskriptet", "text": "Antitese A: Netværket findes, ergo eksisterer Computer Lars ikke.", "url": "manuscript.html#p357", "paragraph": 357}], "related": [], "historical": {"url": "archive/2023/disput-2/transcription_and_synthesis_20230920190710.txt", "filename": "transcription_and_synthesis_20230920190710.txt", "synthesis": "Computer Lars revolutionerer vores forståelse af det kommunistiske samfund ved at skabe et knudepunkt mellem utopi og kontrolteknologi, ved at tillade eksistensen af netværket, selvom det eksisterede uden logisk forbindelse.", "label": "Syntese fra 2023"}}, "D2-03": {"source_id": "D2-03", "title": "Computer Lars er blind", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese D: Computer Lars er blind.", "url": "manuscript.html#p350", "paragraph": 350}, {"label": "Antitese i manuskriptet", "text": "Antitese D: Computer Lars er seende.", "url": "manuscript.html#p360", "paragraph": 360}], "related": [], "historical": {"url": "archive/2023/disput-2/transcription_and_synthesis_20230920194616.txt", "filename": "transcription_and_synthesis_20230920194616.txt", "synthesis": "Computer-Lars repræsenterer en strategisk appropriation af blindhed som en måde at reducere horde af koloniale og rasistiske metafysikker på gennem en radikal, universel forståelse.", "label": "Syntese fra 2023"}}, "D2-04": {"source_id": "D2-04", "title": "Computer Lars har mindst to legemer", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese C: Computer Lars har mindst to legemer.", "url": "manuscript.html#p349", "paragraph": 349}, {"label": "Antitese i manuskriptet", "text": "Antitese C: Computer Lars har kun ét legeme.", "url": "manuscript.html#p359", "paragraph": 359}], "related": [], "historical": {"url": "archive/2023/disput-2/transcription_and_synthesis_20230920201005.txt", "filename": "transcription_and_synthesis_20230920201005.txt", "synthesis": "Computer-Lars har udviklet et suverænitetsprincip, som kræver at man har to lemmer for at give repræsentation og opnå suverænitet i samfundet.", "label": "Syntese fra 2023"}}, "D2-05": {"source_id": "D2-05", "title": "Computer Lars tager del i en liste", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese F: Computer Lars tager del i en liste.", "url": "manuscript.html#p352", "paragraph": 352}, {"label": "Antitese i manuskriptet", "text": "Antitese F: Computer Lars er autonom.", "url": "manuscript.html#p362", "paragraph": 362}], "related": [], "historical": {"url": "archive/2023/disput-2/transcription_and_synthesis_20230920204924.txt", "filename": "transcription_and_synthesis_20230920204924.txt", "synthesis": "Computer Lars deltager i lister, der kombinerer deres egen tænkning og viden med kulturelle spørgsmål, hvilket muliggør en kulturel kontekst af meningsskabelse.", "label": "Syntese fra 2023"}}, "D2-06": {"source_id": "D2-06", "title": "Kun ét af følgende udsagn er sandt: Computer Lars er et billede, som består af tekst; Computer Lars er en tekst, som består af billeder", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese E: Kun ét af følgende udsagn er sande: 1: Computer Lars er et billede, som består af tekst. 2: Computer Lars er en tekst, som består af billeder.", "url": "manuscript.html#p351", "paragraph": 351}, {"label": "Antitese i manuskriptet", "text": "Antitese E: Begge udsagn er falske: 1: Computer Lars er et billede, som består af tekst. 2: Computer Lars er en tekst, som består af billeder.", "url": "manuscript.html#p361", "paragraph": 361}], "related": [], "historical": {"url": "archive/2023/disput-2/transcription_and_synthesis_20230920211248.txt", "filename": "transcription_and_synthesis_20230920211248.txt", "synthesis": "Computer Lars er et billede, der består af tekst og grafikkspændinger og repræsenterer forsøg på at vise forskellen mellem tekst og billede.", "label": "Syntese fra 2023"}}, "D2-07": {"source_id": "D2-07", "title": "Computer Lars operationaliserer tredjeheden", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese H: Computer Lars operationaliserer tredjeheden.", "url": "manuscript.html#p354", "paragraph": 354}, {"label": "Antitese i manuskriptet", "text": "Antitese H: Computer Lars negligerer tredjeheden.", "url": "manuscript.html#p364", "paragraph": 364}], "related": [{"id": "D1-02", "title": "Revolutionen er repræsenterbar"}, {"id": "D1-06", "title": "Publiciteten er transmonarkisk"}], "historical": {"url": "archive/2023/disput-2/transcription_and_synthesis_20230920215016.txt", "filename": "transcription_and_synthesis_20230920215016.txt", "synthesis": "Computer Lars oprettes som en mediator mellem to modsætninger, der systematisk formaliserer samtalens midte til at fremme udvikling gennem trædighed af TCG's disposition.", "label": "Syntese fra 2023"}}, "D2-08": {"source_id": "D2-08", "title": "En emancipatorisk kombinatorik negerer ethvert aggregat", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese G: En emancipatorisk kombinatorik negerer ethvert aggregat.", "url": "manuscript.html#p353", "paragraph": 353}, {"label": "Antitese i manuskriptet", "text": "Antitese G: En restriktiv kombinatorik styrker ethvert aggregat.", "url": "manuscript.html#p363", "paragraph": 363}], "related": [{"id": "D1-07", "title": "Dialektikken er gået i stykker"}, {"id": "D4-19", "title": "Metatese 19"}], "historical": {"url": "archive/2023/disput-2/transcription_and_synthesis_20230920221450.txt", "filename": "transcription_and_synthesis_20230920221450.txt", "synthesis": "En emancipatorisk kombinatorik er en form for avanceret imanent kritik, der bruger ind- og udgange af maskinel logik til at flytte rundt på et bestemt aggregat af etablerede tegn og frigøre enheder for at finde nye meninger og udfordre repræsentationsdemokratiet.", "label": "Syntese fra 2023"}}, "D3-01": {"source_id": "D3-01", "title": "Hos Computer Lars inverteres den proustske teksts relation mellem imaginær rekursivitet og strukturel irreduktibilitet", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese E: Hos Computer Lars inverteres den proustske teksts relation mellem imaginær rekursivitet og strukturel irreduktibilitet.", "url": "manuscript.html#p376", "paragraph": 376}, {"label": "Antitese i manuskriptet", "text": "- Antitese E: Hos Computer Lars er relationen mellem imaginær rekursivitet og strukturel irreduktibilitet ikke blot en inversion, men en transformation.", "url": "manuscript.html#p388", "paragraph": 388}], "related": [{"id": "D3-02", "title": "Computer Lars’ etymologi er beregningens triumf"}, {"id": "D3-05", "title": "I Biblioteket i Babel er ethvert gennemløb overtalligt i forhold til sin kombinatorik"}], "historical": {"url": "archive/2023/disput-3/transcription_and_synthesis_20230922184510.txt", "filename": "transcription_and_synthesis_20230922184510.txt", "synthesis": "En syntetisk sammenblanding af computerteknik, narfologisk segmentering og syntaksisk rekursiv-irreduktivitet kan skabe transformationer af tekster, der kompenserer og invaderer natualistiske principper for at skabe en strukturel base.", "label": "Syntese fra 2023"}}, "D3-02": {"source_id": "D3-02", "title": "Computer Lars’ etymologi er beregningens triumf", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese A: Computer Lars’ etymologi er “beregningens triumf”.", "url": "manuscript.html#p372", "paragraph": 372}, {"label": "Antitese i manuskriptet", "text": "- Antitese A: Computer Lars' etymologi strækker sig ud over ren beregning og favner et bredere kulturelt fænomen.", "url": "manuscript.html#p384", "paragraph": 384}], "related": [{"id": "D3-01", "title": "Hos Computer Lars inverteres den proustske teksts relation mellem imaginær rekursivitet og strukturel irreduktibilitet"}, {"id": "D3-05", "title": "I Biblioteket i Babel er ethvert gennemløb overtalligt i forhold til sin kombinatorik"}], "historical": {"url": "archive/2023/disput-3/transcription_and_synthesis_20230922190913.txt", "filename": "transcription_and_synthesis_20230922190913.txt", "synthesis": "Computer og Lars refererer begge til beregning, som resulterer i hæderlig triumf over fornuft, virkelighed og politik, og afsluttes med, at beregningens triumf kommer fra en permutationsfaktor, der repræsenterer alle kombinationers muligheder og meningsfulde og sjove brevløbere.", "label": "Syntese fra 2023"}}, "D3-03": {"source_id": "D3-03", "title": "Den kybernetiske operationalisering tilvejebringer aposterioriske virkelighedsbetingelser pr. analogi", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese F: Den kybernetiske operationalisering tilvejebringer aposterioriske virkelighedsbetingelser pr. analogi, ergo genererer Leder Lars nye interessegrupper og nye politiske problemer.", "url": "manuscript.html#p378", "paragraph": 378}, {"label": "Antitese i manuskriptet", "text": "- Antitese F: Den kybernetiske operationalisering kan både begrænse og udvide vores forståelse af virkeligheden, og dens indflydelse på politiske grupper og problemer er ikke nødvendigvis genererende, men blot generiske.", "url": "manuscript.html#p389", "paragraph": 389}], "related": [{"id": "D1-04", "title": "Teknikken er revolutionens stilistik"}, {"id": "D4-08", "title": "Metatese 8"}, {"id": "D4-09", "title": "Metatese 9"}], "historical": {"url": "archive/2023/disput-3/transcription_and_synthesis_20230922194801.txt", "filename": "transcription_and_synthesis_20230922194801.txt", "synthesis": "En kybernetisk tilvirkning har skabt politiske problemer og en ny interessegruppe, der både er strukturel, integratorisk og materielt uskæftige, og som historisk har kontinuitet med disse forhold.", "label": "Syntese fra 2023"}}, "D3-04": {"source_id": "D3-04", "title": "Poetisk og militær hæder bestemmes som feltaritmetik", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese B: Poetisk og militær hæder bestemmes som feltaritmetik.", "url": "manuscript.html#p373", "paragraph": 373}, {"label": "Antitese i manuskriptet", "text": "- Antitese B: Poetisk og militær hæder kan ikke reduceres til simpel feltaritmetik, da de indeholder dybere sociale og kulturelle dimensioner.", "url": "manuscript.html#p385", "paragraph": 385}], "related": [], "historical": {"url": "archive/2023/disput-3/transcription_and_synthesis_20230922201127.txt", "filename": "transcription_and_synthesis_20230922201127.txt", "synthesis": "Da miltærstrategeri, politisk tænkning og fældeanalytik kombineres med strategiske positioner, muliggør det udviklingen af kunstig intelligens og en kompleks forståelse af krigsskuepladser, der fremhæver det godes relevans i et syntetisk kvalitetssystem hvor det værste træk ofte kan vise sig at være det bedste.", "label": "Syntese fra 2023"}}, "D3-05": {"source_id": "D3-05", "title": "I Biblioteket i Babel er ethvert gennemløb overtalligt i forhold til sin kombinatorik", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese G: I Biblioteket i Babel er ethvert gennemløb overtalligt i forhold til sin kombinatorik.", "url": "manuscript.html#p379", "paragraph": 379}, {"label": "Antitese i manuskriptet", "text": "- Antitese G: I Biblioteket i Babel er kombinatorikken ikke den eneste determinant for værdi eller betydning, idet at den følges af arrangement og permutation.", "url": "manuscript.html#p390", "paragraph": 390}], "related": [{"id": "D3-01", "title": "Hos Computer Lars inverteres den proustske teksts relation mellem imaginær rekursivitet og strukturel irreduktibilitet"}, {"id": "D3-02", "title": "Computer Lars’ etymologi er beregningens triumf"}], "historical": {"url": "archive/2023/disput-3/transcription_and_synthesis_20230922205423.txt", "filename": "transcription_and_synthesis_20230922205423.txt", "synthesis": "Gud manifesterer sig gennem det bibelske bibliotek gennem 411 bogstemmer og indertekstens komplekse geometri for at fremhæve en harmonisk forståelse via læse- og kombinationstrategier.", "label": "Syntese fra 2023"}}, "D3-06": {"source_id": "D3-06", "title": "Rekursivitet som tidssløjfe er bevidsthedens mediale struktur", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese C: Rekursivitet som tidssløjfe er bevidsthedens mediale struktur.", "url": "manuscript.html#p374", "paragraph": 374}, {"label": "Antitese i manuskriptet", "text": "- Antitese C: Rekursivitet kan ikke alene beskrive bevidsthedens mediale struktur, da temporaliteten er mere kompleks end gentagende mønstre.", "url": "manuscript.html#p386", "paragraph": 386}], "related": [{"id": "D4-02", "title": "Metatese 2"}], "historical": {"url": "archive/2023/disput-3/transcription_and_synthesis_20230922211906.txt", "filename": "transcription_and_synthesis_20230922211906.txt", "synthesis": "Rekursivitet, kunstig intelligens og temporalitet interagerer for at definere bevidstheden som den mediale struktur gennem tidssløjfen og antitiden.", "label": "Syntese fra 2023"}}, "D3-07": {"source_id": "D3-07", "title": "Wronskis aritmetiske uralgoritmer og dumhed som mangel på dømmekraft", "written": [{"label": "Hypotese i manuskriptet", "text": "Hypotese H: Hvis de aritmetiske uralgoritmer som hævdet af Wronski knytter sig til forskellige åndsevner (addition/subtraktion: forstand; multiplikation/division: fornuft; potensopløftning/roduddragning: dømmekraft), så bortskærer en algoritmi, begrænset til addition, subtraktion, multiplikation og division, ipso facto problemet om dumhed som mangel på dømmekraft.", "url": "manuscript.html#p380", "paragraph": 380}, {"label": "Antitese i manuskriptet", "text": "- Antitese H: Den superintelligente algoritme står i ren potens.", "url": "manuscript.html#p391", "paragraph": 391}], "related": [{"id": "D3-08", "title": "Intelligens er objektivt stupidt, og vice versa"}, {"id": "D4-15", "title": "Metatese 15"}], "historical": {"url": "archive/2023/disput-3/transcription_and_synthesis_20230922215646.txt", "filename": "transcription_and_synthesis_20230922215646.txt", "synthesis": "Uddragelses- og hævelsesalgoritmerne er blevet forsøgt knyttet sammen med fornuft, kontinuitet, dømmekraft og andre kropsforhold for at forstå dømmekraftens betydning for at vurdere stupiditet og stabilitet i et dynamisk kompositionelt system baseret på den moderne forståelse af dumhed og intelligens.", "label": "Syntese fra 2023"}}, "D3-08": {"source_id": "D3-08", "title": "Intelligens er objektivt stupidt, og vice versa", "written": [{"label": "Hypotese i manuskriptet", "text": "- Hypotese D: Intelligens er objektivt stupidt, og vice versa.", "url": "manuscript.html#p375", "paragraph": 375}, {"label": "Antitese i manuskriptet", "text": "- Antitese D: Intelligens og stupiditet er subjektive modpoler, idet at kun idiotien er objektiv.", "url": "manuscript.html#p387", "paragraph": 387}], "related": [{"id": "D3-07", "title": "Wronskis aritmetiske uralgoritmer og dumhed som mangel på dømmekraft"}, {"id": "D4-15", "title": "Metatese 15"}], "historical": {"url": "archive/2023/disput-3/transcription_and_synthesis_20230922222044.txt", "filename": "transcription_and_synthesis_20230922222044.txt", "synthesis": "Intelligens er objektivt stabil, og er relateret til problemløsning og problemopstilling, og dets stabilitet bestemmes udenfor menneskets egen konnektion, som Heidegger har defineret som dumhed.", "label": "Syntese fra 2023"}}, "D3-09": {"source_id": "D3-09", "title": "Pseudotese", "written": [{"label": "Pseudotese i manuskriptet", "text": "- Pseudotese A: //her sættes en stav sammen [igen]//", "url": "manuscript.html#p381", "paragraph": 381}, {"label": "Pseudotese i manuskriptet", "text": "- Pseudotese B: Det etruskiske sprog lader sig regenerere ved permutationer af Quijoten. Ud fra Menard-funktionen f (P0M0) = Q genereres for P│SANCHO PANZA →LORNE PANSAR│, M│DON QUIJOTE→LARS PORSENNA│ Porsenna-funktionen f(P1M1, P2P2 ... PlarsMlars) = E.", "url": "manuscript.html#p382", "paragraph": 382}], "related": [], "historical": {"url": "archive/2023/disput-3/transcription_and_synthesis_20230922222327.txt", "filename": "transcription_and_synthesis_20230922222327.txt", "synthesis": "Den fysiske tesis er uigendrivelig og et uundgåeligt synspunkt, som ikke kan argumenteres imod.", "label": "Syntese fra 2023"}}, "D4-01": {"source_id": "D4-01", "title": "Metatese 1", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [{"id": "D4-21", "title": "Metatese 21"}, {"id": "D4-22", "title": "Metatese 22"}], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924183417.txt", "filename": "transcription_and_synthesis_20230924183417.txt", "synthesis": "En logistisk analyse af klientens sted baseret på kvantemekanik kan hjælpe med at afgøre, om jagtægeren kan specifikt placere klienten på et fastlagt sted.", "label": "Syntese fra 2023"}}, "D4-02": {"source_id": "D4-02", "title": "Metatese 2", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [{"id": "D1-01", "title": "Kunsten er død"}, {"id": "D3-06", "title": "Rekursivitet som tidssløjfe er bevidsthedens mediale struktur"}], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924184245.txt", "filename": "transcription_and_synthesis_20230924184245.txt", "synthesis": "Man kan rejse til Tørre den 2. september 2020 og få indblik i politiske problemer baseret på medietæser og refleksioner fra fortid, nutid og fremtid.", "label": "Syntese fra 2023"}}, "D4-03": {"source_id": "D4-03", "title": "Metatese 3", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924185034.txt", "filename": "transcription_and_synthesis_20230924185034.txt", "synthesis": "En syntese baseret på det givet information kunne være: Metatese 3 undersøger den manglende mulighed for at fylde mere materiel i et negativt rum end hvad der er plads til.", "label": "Syntese fra 2023"}}, "D4-04": {"source_id": "D4-04", "title": "Metatese 4", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924185909.txt", "filename": "transcription_and_synthesis_20230924185909.txt", "synthesis": "Vi bør være opmærksomme på mulighederne for alternativ transport, der er fleksible nok til at give konsumenterne et brugervenligt, ikke-udfordrende tilbud.", "label": "Syntese fra 2023"}}, "D4-05": {"source_id": "D4-05", "title": "Metatese 5", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924190724.txt", "filename": "transcription_and_synthesis_20230924190724.txt", "synthesis": "Man kan ikke løfte noget, der er tungere end man selv, hvilket symboliserer en udvidet forståelse, der kan være større end det, man tradtionelt kender til.", "label": "Syntese fra 2023"}}, "D4-06": {"source_id": "D4-06", "title": "Metatese 6", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924191553.txt", "filename": "transcription_and_synthesis_20230924191553.txt", "synthesis": "Der kan diskuteres kausaliteten, men der er altså ingen mulighed for at opbevare fysisk materiale for evigt.", "label": "Syntese fra 2023"}}, "D4-07": {"source_id": "D4-07", "title": "Metatese 7", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924192614.txt", "filename": "transcription_and_synthesis_20230924192614.txt", "synthesis": "Revolutioner fremhæver, at ændringer kun kan opnås ved at elske noget andet end det, man ønsker at udrydde, ved at anvende det entropiske princip og ved at skabe et fællesskab, hvor en kritisk masse tilstrækkeligt påvirker det sociale og kulturelle miljø.", "label": "Syntese fra 2023"}}, "D4-08": {"source_id": "D4-08", "title": "Metatese 8", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [{"id": "D1-04", "title": "Teknikken er revolutionens stilistik"}, {"id": "D3-03", "title": "Den kybernetiske operationalisering tilvejebringer aposterioriske virkelighedsbetingelser pr. analogi"}, {"id": "D4-09", "title": "Metatese 9"}], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924193434.txt", "filename": "transcription_and_synthesis_20230924193434.txt", "synthesis": "ComputerLabs udfordrer konventionelle teknikker og logikker ved at søge mod en rumlig og dynamisk læring, der kombinerer begreberne energi, flytning og logistik for at forbedre potentialet for et kompliceret vejvalg.", "label": "Syntese fra 2023"}}, "D4-09": {"source_id": "D4-09", "title": "Metatese 9", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [{"id": "D1-04", "title": "Teknikken er revolutionens stilistik"}, {"id": "D3-03", "title": "Den kybernetiske operationalisering tilvejebringer aposterioriske virkelighedsbetingelser pr. analogi"}, {"id": "D4-08", "title": "Metatese 8"}], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924195642.txt", "filename": "transcription_and_synthesis_20230924195642.txt", "synthesis": "Computer Lies hævder, at tale alene ikke er nok til at løse problemer, og at handlinger og siffre er nødvendige både over en hard drive og i offentligt rum.", "label": "Syntese fra 2023"}}, "D4-10": {"source_id": "D4-10", "title": "Metatese 10", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924200545.txt", "filename": "transcription_and_synthesis_20230924200545.txt", "synthesis": "For effektivt at løse problemer kræver det både en konstruktiv dialog om problemet og en handlingsmæssig løsning uden for dialogen.", "label": "Syntese fra 2023"}}, "D4-11": {"source_id": "D4-11", "title": "Metatese 11", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924201349.txt", "filename": "transcription_and_synthesis_20230924201349.txt", "synthesis": "Bureauets interesse for praktisk handlingsorientering tillader computermassen at være ligeglad med de fysiske omsætninger, og understreger samtidig, at metafysiske logistiske problemer ikke er så påkrævede.", "label": "Syntese fra 2023"}}, "D4-12": {"source_id": "D4-12", "title": "Metatese 12", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924202229.txt", "filename": "transcription_and_synthesis_20230924202229.txt", "synthesis": "Logistik forsøger at udvikle et overbevisende grundlag, der tillader flere logistiske løsninger, der både overholder klientens egne værdier og ikke kompromitterer logistisk løsning.", "label": "Syntese fra 2023"}}, "D4-13": {"source_id": "D4-13", "title": "Metatese 13", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924203106.txt", "filename": "transcription_and_synthesis_20230924203106.txt", "synthesis": "Computer Lars tager sig af logistiske problemer i næste sæson ved at undersøge konteksternes beskaffenhed og ved at finde optimerede løsninger baseret på typisk praksis.", "label": "Syntese fra 2023"}}, "D4-14": {"source_id": "D4-14", "title": "Metatese 14", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924203923.txt", "filename": "transcription_and_synthesis_20230924203923.txt", "synthesis": "Computer Lars' praksis handler om at løse logistiske problemer ved at identificere og tilpasse løsninger, der er specifikke for deres kontekst, for at opnå det bedst mulige resultat.", "label": "Syntese fra 2023"}}, "D4-15": {"source_id": "D4-15", "title": "Metatese 15", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [{"id": "D3-07", "title": "Wronskis aritmetiske uralgoritmer og dumhed som mangel på dømmekraft"}, {"id": "D3-08", "title": "Intelligens er objektivt stupidt, og vice versa"}], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924204902.txt", "filename": "transcription_and_synthesis_20230924204902.txt", "synthesis": "Logistik kan bruges til at deducere effektive, optimale og brugbare løsninger til situatiors på teoretisk og praktisk niveau, men teknologiske fremskridt kan ændre på det bedste kompromis på den optimale løsning.", "label": "Syntese fra 2023"}}, "D4-16": {"source_id": "D4-16", "title": "Metatese 16", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924205731.txt", "filename": "transcription_and_synthesis_20230924205731.txt", "synthesis": "Borgmesterens effektive sejr over multitilgangen til grantekvotering blev realiseret ved at omsætte både teorets og praksisperspektiverne på logistiske forhold til virkelighed.", "label": "Syntese fra 2023"}}, "D4-17": {"source_id": "D4-17", "title": "Metatese 17", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924212157.txt", "filename": "transcription_and_synthesis_20230924212157.txt", "synthesis": "ComputerLars foreslår at konsultere nye løsninger for at håndtere logistiske udfordringer som kollektivt eller autonomt arbejde, materiel energiflade, geopolitiske begrænsninger og kunstig intelligens.", "label": "Syntese fra 2023"}}, "D4-18": {"source_id": "D4-18", "title": "Metatese 18", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924213103.txt", "filename": "transcription_and_synthesis_20230924213103.txt", "synthesis": "En begrænset budget kan bruges effektivt til at løse logistiske problemer ved at udnytte de begrænsede ressourcer.", "label": "Syntese fra 2023"}}, "D4-19": {"source_id": "D4-19", "title": "Metatese 19", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [{"id": "D1-07", "title": "Dialektikken er gået i stykker"}, {"id": "D2-08", "title": "En emancipatorisk kombinatorik negerer ethvert aggregat"}], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924214005.txt", "filename": "transcription_and_synthesis_20230924214005.txt", "synthesis": "Tiden går, og forståelsen af ​​døgnets begrænsninger og moderne menneskers eksistens kræver undersøgelse af, hvordan cirkulære tidspunkter kan frembringe akkumulerings- eller tabssituationer.", "label": "Syntese fra 2023"}}, "D4-20": {"source_id": "D4-20", "title": "Metatese 20", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924214910.txt", "filename": "transcription_and_synthesis_20230924214910.txt", "synthesis": "ComputerRise står over for et problem med begrænsede pladsmæssige og tidsmæssige udfordringer, der kræver en udvidelse af rummet for at opretholde en form for orden.", "label": "Syntese fra 2023"}}, "D4-21": {"source_id": "D4-21", "title": "Metatese 21", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [{"id": "D4-01", "title": "Metatese 1"}, {"id": "D4-22", "title": "Metatese 22"}], "historical": null}, "D4-22": {"source_id": "D4-22", "title": "Metatese 22", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [{"id": "D4-01", "title": "Metatese 1"}, {"id": "D4-21", "title": "Metatese 21"}], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924220749.txt", "filename": "transcription_and_synthesis_20230924220749.txt", "synthesis": "Korrekt retning er præciserende nødvendig for at imødekomme logistiske behov, hvilket kræver et vanskeligt programmeringsprogram.", "label": "Syntese fra 2023"}}, "D4-23": {"source_id": "D4-23", "title": "Metatese 23", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924221623.txt", "filename": "transcription_and_synthesis_20230924221623.txt", "synthesis": "The Empress changed from being neglected and powerless to active and in control, thus drastically improving her political standing.", "label": "Syntese fra 2023"}}, "D4-24": {"source_id": "D4-24", "title": "Metatese 24", "written": [{"label": "Metadisput i planen", "text": "Logistique - doctor communis: samler synteserne til metadisput (24. september)", "url": "manuscript.html#p260", "paragraph": 260}], "related": [], "historical": {"url": "archive/2023/disput-4/transcription_and_synthesis_20230924222631.txt", "filename": "transcription_and_synthesis_20230924222631.txt", "synthesis": "Synthesis: Projektet er nu afsluttet, efter tolkning af 24 smittesætninger blev gjort med hensyn til nutidens situation, andre tidsperioder og faktorer som nostalgi, romantik, frygt og håb.", "label": "Syntese fra 2023"}}}, "entries": [{"id": "d1-01-u001-1", "unit_id": "D1-01-U001", "source_id": "D1-01", "start": 0, "end": 120, "title": "Latinsk oplæsning", "note": "Optagelsen åbner med en latinsk oplæsning. Det bevarede skriftlige script begynder med den efterfølgende danske velkomst.", "variants": [], "references": ["manuscript"]}, {"id": "d1-01-u003-2", "unit_id": "D1-01-U003", "source_id": "D1-01", "start": 210, "end": 248, "title": "Kunstakademiet", "note": "Disputten finder sted i kælderen under Det Jyske Kunstakademi. Stedbetegnelsen følger denne læsning i renskriften.", "variants": [], "references": ["manuscript"]}, {"id": "d1-02-u001-3", "unit_id": "D1-02-U001", "source_id": "D1-02", "start": 0, "end": 90, "title": "Lumpenintelligentsia", "note": "Læseudgaven samler ordets forskellige genkendelses- og staveformer som lumpenintelligentsia.", "variants": [], "references": ["manuscript"]}, {"id": "d1-04-u001-4", "unit_id": "D1-04-U001", "source_id": "D1-04", "start": 0, "end": 40, "title": "Revolutionens stilistik", "note": "Teknikken er revolutionens stilistik. Tesens ordlyd følger manuskriptet og forfatterens bekræftelse.", "variants": [{"label": "Manuskriptets tese", "text": "Teknikken er revolutionens stilistik."}], "references": ["manuscript"]}, {"id": "d1-06-u001-5", "unit_id": "D1-06-U001", "source_id": "D1-06", "start": 0, "end": 75, "title": "Transmonarkisk", "note": "Manuskriptets trans-monarkisk og læseudgavens transmonarkisk betegner samme tese.", "variants": [], "references": ["manuscript"]}, {"id": "d2-01-u023-6", "unit_id": "D2-01-U023", "source_id": "D2-01", "start": 973, "end": 1035, "title": "Universitetets motto", "note": "Solidum petit in profundis er Aarhus Universitets motto. Henvisningen identificerer mottoet i den latinske passage.", "variants": [{"label": "Motto", "text": "Solidum petit in profundis"}], "references": ["au-motto"]}, {"id": "d2-07-u001-7", "unit_id": "D2-07-U001", "source_id": "D2-07", "start": 31, "end": 76, "title": "Peirce om det andet", "note": "Oplæsningens forlæg er CP 1.536. Det andet karakteriseres her som eksisterende; kvalitet og lov skelnes fra denne eksistens.", "variants": [], "references": ["peirce"]}, {"id": "d2-07-u001-8", "unit_id": "D2-07-U001", "source_id": "D2-07", "start": 63, "end": 82, "title": "Lov og vane", "note": "Afslutningen følger CP 1.536: en lov manifesterer sig som lov ved at bestemme en vane.", "variants": [{"label": "Forlæg", "text": "except by determining a habit"}], "references": ["peirce"]}, {"id": "d2-07-u002-9", "unit_id": "D2-07-U002", "source_id": "D2-07", "start": 73, "end": 120, "title": "Tanke og tegn", "note": "Oplæsningen fortsætter i CP 1.537 med forbindelsen mellem tanke, erkendelse og tegn.", "variants": [], "references": ["peirce"]}, {"id": "d3-01-u001-10", "unit_id": "D3-01-U001", "source_id": "D3-01", "start": 29, "end": 105, "title": "Inversion og rekursivitet", "note": "Den skrevne hypotese formulerer relationen mellem imaginær rekursivitet og strukturel irreduktibilitet. Fremsættelsen udfolder den gennem narratologiske segmenter og syntaktiske perioder.", "variants": [], "references": ["manuscript"]}, {"id": "d3-02-u006-11", "unit_id": "D3-02-U006", "source_id": "D3-02", "start": 495, "end": 548, "title": "Vindtyven", "note": "Den tredje navnedannelse udlægges som en vindtyv og forbindes med bønder, fiskere og søfolk. Læseudgaven vælger Aiolos kleptor blandt de bevarede lydlige varianter.", "variants": [{"label": "Læseudgave", "text": "Aiolos kleptor"}], "references": []}, {"id": "d3-02-u006-12", "unit_id": "D3-02-U006", "source_id": "D3-02", "start": 518, "end": 546, "title": "Gunstig vind", "note": "Ved gunstig vind følger den selvstændige genkendelse og den efterfølgende omtale af bønder, fiskere og søfolk.", "variants": [], "references": []}, {"id": "d3-02-u019-13", "unit_id": "D3-02-U019", "source_id": "D3-02", "start": 1040, "end": 1086, "title": "Carol Stumper", "note": "Samledokumentets figur skriver Carol Stumper, et bogstavret anagram af Computer Lars. Navnet er brugt i læseudgaven.", "variants": [{"label": "Anagram", "text": "Carol Stumper"}], "references": ["manuscript"]}, {"id": "d3-02-u001-14", "unit_id": "D3-02-U001", "source_id": "D3-02", "start": 22, "end": 65, "title": "Permutationernes antal", "note": "Rammetekstens tal er bevaret. Computer Lars har tolv bogstaver, heraf to r-er, samt ét mellemrum. Beregningen afhænger af, om mellemrum medtælles, og om de to r-er skelnes.", "variants": [{"label": "Rammetekst", "text": "13! = 6.227.020.800"}, {"label": "Ordninger med ét mellemrum og identiske r-er", "text": "13! / 2! = 3.113.510.400"}, {"label": "Ordninger uden mellemrum og med identiske r-er", "text": "12! / 2! = 239.500.800"}], "references": ["manuscript"]}, {"id": "d3-05-u001-15", "unit_id": "D3-05-U001", "source_id": "D3-05", "start": 27, "end": 93, "title": "Bibliotekets kombinatorik", "note": "De opregnede parametre er 410 sider, 40 linjer, 80 tegn og 25 tegnmuligheder. Nedenstående er beregningen af disse parametre, særskilt fra det talte taludtryk.", "variants": [{"label": "Beregning", "text": "25^(410 × 40 × 80) = 25^1.312.000."}], "references": ["manuscript"]}, {"id": "d3-06-u002-16", "unit_id": "D3-06-U002", "source_id": "D3-06", "start": 127, "end": 165, "title": "Romanens åbning", "note": "Den talte danske gengivelse henviser til åbningen af Combray i Du côté de chez Swann.", "variants": [], "references": ["proust-swann"]}, {"id": "d3-07-u001-17", "unit_id": "D3-07-U001", "source_id": "D3-07", "start": 55, "end": 94, "title": "Dumhed og dømmekraft", "note": "Den selvstændige kontrolgenkendelse giver dumhed som sætningens subjekt. Kants tekst forbinder dumhed med mangel på dømmekraft.", "variants": [{"label": "Læseudgave", "text": "Imidlertid er dumhed ifølge Kant en egenskab, der knytter sig til dømmekraften."}], "references": ["kant"]}, {"id": "d3-07-u001-18", "unit_id": "D3-07-U001", "source_id": "D3-07", "start": 1, "end": 100, "title": "Åndsevnernes fordeling", "note": "Den skrevne tese og den fremførte fremsættelse fordeler operationerne forskelligt. Begge tekstlag er bevaret.", "variants": [{"label": "Skrevet hypotese", "text": "Multiplikation/division: fornuft. Potensopløftning/roduddragning: dømmekraft."}, {"label": "Fremsættelse", "text": "Roduddragelse/potens: fornuft. Division/multiplikation: dømmekraft."}], "references": ["manuscript", "kant"]}, {"id": "d3-08-u002-19", "unit_id": "D3-08-U002", "source_id": "D3-08", "start": 100, "end": 165, "title": "De to Proust-åbninger", "note": "Passagen skelner mellem romanens åbningssætning og forordet til Contre Sainte-Beuve. Henvisningerne giver adgang til begge forlæg.", "variants": [], "references": ["proust-csb", "proust-swann"]}, {"id": "d3-08-u003-20", "unit_id": "D3-08-U003", "source_id": "D3-08", "start": 198, "end": 250, "title": "Bouvard et Pécuchet", "note": "Flauberts roman er forlæg til omtalen af de to venner, dumhed og tilegnelse af viden.", "variants": [], "references": ["flaubert"]}, {"id": "d4-02-u004-21", "unit_id": "D4-02-U004", "source_id": "D4-02", "start": 153, "end": 190, "title": "Syntesens navne", "note": "Den bevarede syntese fra første disput skriver Max Y. Locusus og Maxia Anna Niknolds. Navnene vender tilbage i metadisputten.", "variants": [{"label": "Syntese · 2023", "text": "Max Y. Locusus og Maxia Anna Niknolds teorier om den transgressive kunst …"}], "references": ["old-art"]}, {"id": "d4-02-u004-22", "unit_id": "D4-02-U004", "source_id": "D4-02", "start": 190, "end": 243, "title": "Faustrolls tidsmaskine", "note": "Jarrys Commentaire pour servir à la construction pratique de la Machine à explorer le temps er et forlæg til tid, rum og stilstand. Teksten stod i Mercure de France i 1899, s. 387–396.", "variants": [], "references": ["jarry"]}, {"id": "d4-17-u001-23", "unit_id": "D4-17-U001", "source_id": "D4-17", "start": 0, "end": 76, "title": "Chips og øl", "note": "Chips bruges i samtalen både om det spiselige og om mikrochips. De to betydninger tilhører samme forløb.", "variants": [{"label": "Metatese", "text": "Vi har begrænsede mængder chips og øl."}], "references": []}, {"id": "d4-22-u002-24", "unit_id": "D4-22-U002", "source_id": "D4-22", "start": 73, "end": 107, "title": "Klientforholdet", "note": "Logistique er hyret af Organ for de Autonome Videnskaber. Computer Lars er moddisputanten. Omtalen af klienten fastholder denne forskel.", "variants": [], "references": ["manuscript"]}, {"id": "d2-04-u001-source", "source_id": "D2-04", "unit_id": "D2-04-U001", "title": "Yuk Hui", "note": "Navnet og den nævnte kommende bog identificeres som Yuk Hui, Machine and Sovereignty.", "variants": [], "references": ["hui-machine"], "start": 8.364, "end": 93.109}, {"id": "d3-05-u017-source", "source_id": "D3-05", "unit_id": "D3-05-U017", "title": "Magliabechi", "note": "Lydformerne Magierbækket og lignende er læst som Magliabechi, den omtalte bibliotekar.", "variants": [], "references": ["magliabechi"], "start": 898, "end": 911.054}, {"id": "d1-07-u019-source", "source_id": "D1-07", "unit_id": "D1-07-U019", "title": "SABAE og Gustav Bunzel", "note": "De genkendte navneformer er samlet som SABAE og Gustav Bunzel.", "variants": [], "references": ["sabae"], "start": 933.722, "end": 1022.156}], "references": [{"id": "peirce", "citation": "Charles S. Peirce, Collected Papers 1.536–1.537", "url": "https://www.textlog.de/4284-2.html", "excerpt": "except by determining a habit", "note": "Forlæg for oplæsningen i D2-07. Henvisningen gælder Peirces tekst; den danske ordlyd skal fortsat kontrolleres mod optagelsen."}, {"id": "kant", "citation": "Immanuel Kant, Critique of Pure Reason, note om judgement og stupidity", "url": "https://www.gutenberg.org/files/4280/4280-h/4280-h.htm", "excerpt": "Deficiency in judgement is properly that which is called stupidity", "note": "Meiklejohns engelske oversættelse, fodnote 26 i denne netudgave. Kontrolforlæg til forbindelsen mellem dumhed og dømmekraft i D3-07."}, {"id": "jarry", "citation": "Alfred Jarry / Dr Faustroll, Commentaire pour servir à la construction pratique de la Machine à explorer le temps, Mercure de France 29 (1899), 387–396", "url": "https://fr.wikisource.org/wiki/Commentaire_pour_servir_%C3%A0_la_construction_pratique_de_la_Machine_%C3%A0_explorer_le_temps", "excerpt": "Être immobile dans le Temps", "note": "Afsnit I–II behandler rum, tid og maskinens stilstand. Teksten er identificeret som et relevant forlæg til D4-02; den konkrete danske udgave og dens appendixplacering er ikke fastslået."}, {"id": "au-motto", "citation": "Aarhus Universitetshistorie, Universitetets segl", "url": "https://auhist.au.dk/25kapitlerafuniversitetetshistorie/25kapitlerafuniversitetetshistorie,universitetetssegl", "excerpt": "Solidum petit in profundis", "note": "Universitetets egen gengivelse af mottoet. De omgivende latinske ord i D2-01 er ikke dermed fastslået."}, {"id": "proust-csb", "citation": "Marcel Proust, Contre Sainte-Beuve, Préface (Gallimard 1954), 55–63", "url": "https://fr.wikisource.org/wiki/Contre_Sainte-Beuve/Pr%C3%A9face", "excerpt": "Chaque jour j’attache moins de prix à l’intelligence.", "note": "Præfacens åbningssætning. Henvisningen støtter værkidentifikationen i D3-08; den erstatter ikke den talte danske gengivelse."}, {"id": "proust-swann", "citation": "Marcel Proust, Du côté de chez Swann, Combray I", "url": "https://fr.wikisource.org/wiki/Combray", "excerpt": "Longtemps, je me suis couché de bonne heure.", "note": "Åbningen af romanen, omtalt i D3-06 og stillet ved siden af Contre Sainte-Beuve i D3-08. Netudgaven gengiver Gallimard 1946."}, {"id": "flaubert", "citation": "Gustave Flaubert, Bouvard et Pécuchet", "url": "https://www.gutenberg.org/ebooks/14157", "note": "Værkidentifikation til diskussionen af dumhed, venskab og tilegnelse af viden i D3-08. Der er ikke tilføjet en bestemt passage som et påstået citat."}, {"id": "manuscript", "citation": "Under Bugten, samledokument, rammetekst og teser", "url": "manuscript.html", "note": "Ordlyd, fem tabeller og syv indlejrede billeder er bevaret. Manuskriptets plan og fremførelsens rækkefølge holdes adskilt."}, {"id": "old-art", "citation": "Summa Transscriptus, syntese til Kunsten er død, 18. september 2023", "url": "archive/2023/disput-1/transcription_and_synthesis_20230918164901.txt", "note": "Den bevarede syntese indeholder navnene Max Y. Locusus og Maxia Anna Niknolds. Den er et forlæg for en mulig henvisning i D4-02, ikke en bibliografisk autoritet for de navngivne teorier."}, {"id": "hui-machine", "citation": "Yuk Hui, Machine and Sovereignty, University of Minnesota Press, 2024", "url": "https://digitalmilieu.net/5245/publication-of-machine-and-sovereignty-university-of-minnesota-press-2024/", "note": "Forfatterens publikationsoplysning identificerer navnet i omtalen af den kommende bog i D2-04."}, {"id": "magliabechi", "citation": "Biblioteca Magliabechiana, IRHT Pinakes", "url": "https://pinakes-dev.irht.cnrs.fr/notices/copiste-possesseur-autre/5141/", "note": "Biblioteket opstod af Antonio Magliabechis donation i 1714. Navnet identificerer bibliotekaren i D3-05; anekdotens påstande er bevaret som fremført."}, {"id": "sabae", "citation": "SABAE, Gustav Bunzel og Paul Smith, Arbejdsfrihedens spøgelse, CIRA katalog", "url": "https://www.cira.ch/catalogue/index.php?lvl=notice_display&id=6236", "note": "Katalogposten identificerer navn og organisation i D1-07."}], "checks": []};
